# libagentxx 共享库导出符号白名单 (ELF version script)
#
# 目标: 将 libagentxx.so 导出面从"全部 C++ 符号 (约 17 万)"收敛为仅 FFI C API,
# 供其他语言 FFI 干净调用 (dlopen/dlsym 只按名查找白名单符号):
#   - 共 15 个符号 (agentxx/ffi_api.h): 内存/版本/生命周期 + call / call_cancel +
#     两个本地同步查询 (get_capabilities / drain_logs)
#   - 领域操作全部走 agentxx_ffi_call 的 op, 新增能力只加 op 名, 不再加符号
# local: * 隐藏其余全部符号 (libagentxx 内部 C++ 符号、静态链接的第三方库
#         符号: fmt/asio/sqlite/hyperscan/neograph 等), 避免污染 FFI 命名空间
#
# 构建侧注入 (agent/lib/CMakeLists.txt):
#   target_link_options(agentxx_shared PRIVATE "-Wl,--version-script=<本文件>")
# 仅作用于共享库; agentxx_static (cli/test/benchmark 处理) 不受影响。
# Windows 侧从同一份文件解析 `agentxx_ffi_*` 生成导出列表, 因此改符号只改这里。
#
# 注意: 新增导出符号时在此追加 (同时更新 agentxx/ffi_api.h 与文档)。
{
  global:
    agentxx_ffi_malloc;
    agentxx_ffi_free;
    agentxx_ffi_string_free;
    agentxx_ffi_strdup_n;
    agentxx_ffi_api_version;
    agentxx_ffi_library_version;
    agentxx_ffi_strerror;
    agentxx_ffi_get_capabilities;
    agentxx_ffi_create;
    agentxx_ffi_start;
    agentxx_ffi_stop;
    agentxx_ffi_destroy;
    agentxx_ffi_call;
    agentxx_ffi_call_cancel;
    agentxx_ffi_drain_logs;
  local: *;
};
